/**
 * GET /api/role-permissions
 * Returns the full role_permissions matrix for the current studio's plan.
 * Used by the PermissionsMatrix UI component on the permissions settings page.
 *
 * Only owners and admins can access this endpoint.
 */
export async function GET(_request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  if (authUser.role !== 'owner' && authUser.role !== 'admin') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  try {
    const supabase = await createClient()

    const { data, error } = await supabase
      .from('role_permissions')
      .select('id, role, permission_key, granted')
      .order('role', { ascending: true })
      .order('permission_key', { ascending: true })

    if (error) {
      logger.error({ err: error }, 'role-permissions GET failed')
      return NextResponse.json({ error: 'Failed to fetch permissions' }, { status: 500 })
