/**
 * Booking participants helpers — multi-artist commission split support.
 *
 * The booking_participants table stores one row per artist per booking,
 * with split_pct values summing to 100 across all participants.
 */

import type { SupabaseClient } from '@supabase/supabase-js'
import type { Database } from '@/lib/supabase/types'

export type BookingParticipantRow =
  Database['public']['Tables']['booking_participants']['Row']

export type BookingParticipantInsert =
  Database['public']['Tables']['booking_participants']['Insert']

export type ParticipantRole = BookingParticipantRow['role']

export interface ParticipantInput {
  artist_id: string
  role: ParticipantRole
  split_pct: number
  notes?: string | null
}

export interface SplitValidationResult {
  ok: boolean
  total: number
}

/**
 * Validates that the sum of split_pct across all participants equals 100.
 * Uses a 0.01 epsilon to handle floating-point rounding.
 */
export function validateSplitSum(
  participants: Pick<ParticipantInput, 'split_pct'>[],
): SplitValidationResult {
  const total = participants.reduce((sum, p) => sum + p.split_pct, 0)
  return { ok: Math.abs(total - 100) < 0.01, total }
}

/**
 * Validates that a participant list has exactly one 'primary' role and no
 * duplicate artist_ids.
 */
export function validateParticipantList(participants: ParticipantInput[]): string | null {
  if (participants.length === 0) return 'At least one participant is required'

  const primaryCount = participants.filter((p) => p.role === 'primary').length
  if (primaryCount !== 1) return 'Exactly one primary participant is required'

  const ids = participants.map((p) => p.artist_id)
  const uniqueIds = new Set(ids)
  if (uniqueIds.size !== ids.length) return 'Duplicate artist_ids are not allowed'

  const { ok, total } = validateSplitSum(participants)
  if (!ok) return `Split percentages must sum to 100 (current total: ${total.toFixed(2)})`

  return null
}

/**
 * Fetch all participants for a booking, ordered by split_pct descending
 * (primary first in practice).
 */
export async function fetchBookingParticipants(
  supabase: SupabaseClient,
  bookingId: string,
): Promise<BookingParticipantRow[]> {
  const { data, error } = await (supabase as SupabaseClient & {
    from: (table: 'booking_participants') => ReturnType<typeof supabase.from>
  })
    .from('booking_participants')
    .select('*')
    .eq('booking_id', bookingId)
    .order('split_pct', { ascending: false })

  if (error) throw new Error(error.message)
  return (data ?? []) as BookingParticipantRow[]
}

/**
 * Upsert participants for a booking.
 * Performs: DELETE existing rows for booking_id, then INSERT new list.
 * The caller must validate participants before calling this function.
 *
 * studioId is required for RLS scoping on insert.
 */
export async function upsertBookingParticipants(
  supabase: SupabaseClient,
  bookingId: string,
  studioId: string,
  participants: ParticipantInput[],
): Promise<BookingParticipantRow[]> {
  // Step 1: delete existing
  const { error: deleteError } = await supabase
    .from('booking_participants' as Parameters<typeof supabase.from>[0])
    .delete()
    .eq('booking_id', bookingId)

  if (deleteError) throw new Error(`Delete participants failed: ${deleteError.message}`)

  // Step 2: insert new list
  const inserts: BookingParticipantInsert[] = participants.map((p) => ({
    booking_id: bookingId,
    studio_id: studioId,
    artist_id: p.artist_id,
    role: p.role,
    split_pct: p.split_pct,
    ...(p.notes != null ? { notes: p.notes } : {}),
  }))

  const { data, error: insertError } = await supabase
    .from('booking_participants' as Parameters<typeof supabase.from>[0])
    .insert(inserts)
    .select()

  if (insertError) throw new Error(`Insert participants failed: ${insertError.message}`)
  return (data ?? []) as BookingParticipantRow[]
}

/**
 * Pure commission calculation — no side effects, no DB calls.
 * Used in CommissionPreview, RuleEditorDrawer, and NewBookingDrawer.
 *
 * All amounts are in cents.
 *
 * ─── Commission generation flow ──────────────────────────────────────────────
 * In production a Postgres trigger `handle_booking_complete_commission` fires
 * on UPDATE to bookings.status = 'completed'. For S19 multi-participant
 * bookings the trigger needs to be updated to:
 *
 *   1. Check booking_participants for the booking_id.
 *   2. If rows exist, iterate each participant:
 *      a. Check guest_artist_engagements for the participant's artist_id +
 *         studio_id with status='active' AND scheduled_at::date BETWEEN start_date AND end_date.
 *      b. If engagement found: use split_pct_artist as percentage, flat_fee_cents as flat fee.
 *      c. Else: resolve commission_rules as before (service_specific → catch_all → artist_default).
 *      d. participant_price = booking.price_cents × (participant.split_pct / 100)
 *      e. commission_cents = round(participant_price × pct / 100) + flat_fee
 *      f. tip_commission_cents = round(booking.tip_cents × (participant.split_pct / 100) × tip_split_pct / 100)
 *      g. Insert commission_records row with rule_snapshot including participant context.
 *   3. If no participants exist (backfill gap), fall through to existing single-artist logic
 *      using booking.artist_id as primary@100%.
 *
 * Until the trigger is updated, the app-layer preview below mirrors this logic exactly
 * so CommissionPreview stays accurate.
 */

export interface CommissionPreviewRule {
  percentage: number | null
  flat_fee_cents: number | null
  tip_split_pct: number
}

export interface CommissionPreviewResult {
  commission: number
  tipCommission: number
  total: number
  breakdown: string
}

// ── Single-artist (original) API — unchanged ──────────────────────────────────

/**
 * Calculate artist commission from service price, tip, and rule.
 * Mirrors the trigger logic in `on_booking_completed_commission`.
 *
 * @param price            Service price in cents.
 * @param tip              Tip amount in cents.
 * @param rule             Resolved commission rule (percentage, flat_fee_cents, tip_split_pct).
 *                         May be null/undefined when no rule matched and no artist default exists.
 * @param artistDefaultPct Optional fallback percentage from `artists.commission_default_pct`.
 *                         Used when no rule matches — mirrors the trigger's artist_default path.
 *                         Pass `null` or omit to skip the fallback (returns $0 commission).
 */
export function calculateCommission(
  price: number,
  tip: number,
  rule: CommissionPreviewRule | null | undefined,
  artistDefaultPct: number | null = null,
): CommissionPreviewResult {
  // If no rule supplied, fall back to artist default pct (mirrors trigger behaviour)
  const effectiveRule: CommissionPreviewRule =
    rule ?? (artistDefaultPct != null
      ? { percentage: artistDefaultPct, flat_fee_cents: null, tip_split_pct: 100 }
      : { percentage: null, flat_fee_cents: null, tip_split_pct: 100 })

  let commission = 0
  const parts: string[] = []

  if (effectiveRule.percentage != null && effectiveRule.flat_fee_cents != null) {
    commission =
      Math.round((price * effectiveRule.percentage) / 100) + effectiveRule.flat_fee_cents
    parts.push(`${effectiveRule.percentage}% + flat fee`)
  } else if (effectiveRule.percentage != null) {
    commission = Math.round((price * effectiveRule.percentage) / 100)
    parts.push(`${effectiveRule.percentage}%`)
  } else if (effectiveRule.flat_fee_cents != null) {
    commission = effectiveRule.flat_fee_cents
    parts.push(`flat fee`)
  }

  const tipCommission = Math.round((tip * effectiveRule.tip_split_pct) / 100)
  if (tip > 0 && effectiveRule.tip_split_pct > 0) {
    parts.push(`${effectiveRule.tip_split_pct}% tip`)
  }

  return {
    commission,
    tipCommission,
    total: commission + tipCommission,
    breakdown: parts.join(' + '),
  }
}

// ── Multi-participant API (S19) ───────────────────────────────────────────────

export type ParticipantRole = 'primary' | 'assistant' | 'piercer' | 'apprentice' | 'observer'

export interface ParticipantCommissionInput {
  artistId: string
  role: ParticipantRole
  splitPct: number
  /** If the participant has an active guest engagement, pass their split rates here */
  guestEngagement?: {
    engagementId: string
    splitPctArtist: number
    flatFeeCents: number | null
  } | null
  /** The resolved commission rule for non-guest participants. Null = artist default / no rule */
  rule?: CommissionPreviewRule | null
  /** Artist-level default percentage fallback */
  artistDefaultPct?: number | null
}

export interface ParticipantCommissionResult extends CommissionPreviewResult {
  artistId: string
  role: ParticipantRole
  splitPct: number
  participantRevenueCents: number
  ruleSnapshot: ParticipantRuleSnapshot
}

export interface ParticipantRuleSnapshot {
  source: 'guest_engagement' | 'service_specific' | 'catch_all' | 'artist_default' | 'none'
  engagement_id?: string
  split_pct_artist?: number
  participant_split_pct: number
  booking_participant_role: ParticipantRole
  percentage: number | null
  flat_fee_cents: number | null
  tip_split_pct: number
}

/**
 * Calculate commissions for all participants in a multi-artist booking.
 * Participant split determines their share of booking revenue and tip.
 * Their individual commission rate comes from engagement (guest) or rule (regular).
 *
 * @param bookingPriceCents  Total booking service price in cents.
 * @param bookingTipCents    Total tip in cents.
 * @param participants       Array of participant inputs.
 */
export function calculateParticipantCommissions(
  bookingPriceCents: number,
  bookingTipCents: number,
  participants: ParticipantCommissionInput[],
): ParticipantCommissionResult[] {
  return participants.map((p) => {
    const participantRevenueCents = Math.round(bookingPriceCents * (p.splitPct / 100))
    const participantTipCents = Math.round(bookingTipCents * (p.splitPct / 100))

    let effectiveRule: CommissionPreviewRule
    let snapshot: ParticipantRuleSnapshot

    if (p.guestEngagement != null) {
      // Guest engagement takes precedence
      effectiveRule = {
        percentage: p.guestEngagement.splitPctArtist,
        flat_fee_cents: p.guestEngagement.flatFeeCents,
        tip_split_pct: 100,
      }
      snapshot = {
        source: 'guest_engagement',
        engagement_id: p.guestEngagement.engagementId,
        split_pct_artist: p.guestEngagement.splitPctArtist,
        participant_split_pct: p.splitPct,
        booking_participant_role: p.role,
        percentage: p.guestEngagement.splitPctArtist,
        flat_fee_cents: p.guestEngagement.flatFeeCents,
        tip_split_pct: 100,
      }
    } else {
      // Regular commission rule resolution
      const rule = p.rule
      const fallbackPct = p.artistDefaultPct ?? null
      effectiveRule =
        rule ?? (fallbackPct != null
          ? { percentage: fallbackPct, flat_fee_cents: null, tip_split_pct: 100 }
          : { percentage: null, flat_fee_cents: null, tip_split_pct: 100 })

      const source: ParticipantRuleSnapshot['source'] =
        rule != null ? 'service_specific' : fallbackPct != null ? 'artist_default' : 'none'

      snapshot = {
        source,
        participant_split_pct: p.splitPct,
        booking_participant_role: p.role,
        percentage: effectiveRule.percentage,
        flat_fee_cents: effectiveRule.flat_fee_cents,
        tip_split_pct: effectiveRule.tip_split_pct,
      }
    }

    const result = calculateCommission(
      participantRevenueCents,
      participantTipCents,
      effectiveRule,
    )

    return {
      ...result,
      artistId: p.artistId,
      role: p.role,
      splitPct: p.splitPct,
      participantRevenueCents,
      ruleSnapshot: snapshot,
    }
  })
}

/**
 * Artist goals helpers — CRUD + progress computation.
 *
 * Goals are stored in the artist_goals table. Progress is computed by querying
 * the artist_performance_summary VIEW via rawQuery.
 */

import type { SupabaseClient } from '@supabase/supabase-js'
import { rawQuery } from '@/lib/supabase/raw-query'
import type { ArtistPerformanceSummaryRow } from '@/lib/artists/performance-types'
import type { Database } from '@/lib/supabase/types'

export type GoalRow = Database['public']['Tables']['artist_goals']['Row']
export type GoalInsert = Database['public']['Tables']['artist_goals']['Insert']

export interface GoalInput {
  studio_id: string
  artist_id: string
  period_type: 'month' | 'quarter' | 'year'
  period_start: string
  period_end: string
  metric: 'revenue' | 'bookings' | 'hours' | 'commission' | 'new_clients'
  target_value: number
  set_by?: string | null
  notes?: string | null
}

/**
 * Fetch all goals for an artist in a given period.
 * period is the first day of the desired month/quarter/year as a Date.
 */
export async function fetchArtistGoalsForPeriod(
  supabase: SupabaseClient,
  artistId: string,
  period: Date,
): Promise<GoalRow[]> {
  const periodStr = period.toISOString().split('T')[0] ?? ''

  const { data, error } = await supabase
    .from('artist_goals')
    .select('*')
    .eq('artist_id', artistId)
    .lte('period_start', periodStr)
    .gte('period_end', periodStr)
    .order('metric', { ascending: true })

  if (error) throw new Error(error.message)
  return (data ?? []) as GoalRow[]
}

/**
 * Upsert a goal (insert or update on conflict: artist_id + period_type + period_start + metric).
 */
export async function upsertGoal(
  supabase: SupabaseClient,
  input: GoalInput,
): Promise<GoalRow> {
  const insert: GoalInsert = {
    studio_id: input.studio_id,
    artist_id: input.artist_id,
    period_type: input.period_type,
    period_start: input.period_start,
    period_end: input.period_end,
    metric: input.metric,
    target_value: input.target_value,
    ...(input.set_by != null ? { set_by: input.set_by } : {}),
    ...(input.notes != null ? { notes: input.notes } : {}),
  }

  const { data, error } = await supabase
    .from('artist_goals')
    .upsert(insert, {
      onConflict: 'artist_id,period_type,period_start,metric',
    })
    .select()
    .single()

  if (error) throw new Error(error.message)
  return data as GoalRow
}

/**
 * Compute the current value for a goal by querying artist_performance_summary.
 * For 'new_clients', runs a separate bookings query.
 *
 * Returns the current numeric value for the goal metric over the goal's period.
 */
export async function computeCurrentValueForGoal(
  supabase: SupabaseClient,
  goal: GoalRow,
): Promise<number> {
  if (goal.metric === 'new_clients') {
    return computeNewClientsValue(supabase, goal)
  }

  // Query all monthly rows for the artist within the goal's period
  const rows = await rawQuery<ArtistPerformanceSummaryRow>(supabase, 'artist_performance_summary')
    .select('period_month, revenue_cents, bookings_completed, hours_worked_min, commission_cents')
    .eq('artist_id', goal.artist_id)
    .eq('studio_id', goal.studio_id)
    .gte('period_month', goal.period_start)
    .lte('period_month', goal.period_end)

  const summaryData = (await rows) as { data: ArtistPerformanceSummaryRow[] | null; error: { message: string } | null }
  if (summaryData.error) throw new Error(summaryData.error.message)
  const summaryRows = summaryData.data ?? []

  switch (goal.metric) {
    case 'revenue':
      return summaryRows.reduce((sum, r) => sum + (r.revenue_cents ?? 0), 0)
    case 'bookings':
      return summaryRows.reduce((sum, r) => sum + (r.bookings_completed ?? 0), 0)
    case 'hours':
      // hours_worked_min is in minutes — convert to hours
      return Math.round(summaryRows.reduce((sum, r) => sum + (r.hours_worked_min ?? 0), 0) / 60)
    case 'commission':
      return summaryRows.reduce((sum, r) => sum + (r.commission_cents ?? 0), 0)
    default:
      return 0
  }
}

async function computeNewClientsValue(
  supabase: SupabaseClient,
  goal: GoalRow,
): Promise<number> {
  // Count distinct clients whose first booking with this artist is within the period
  const { data, error } = await supabase
    .from('bookings')
    .select('client_id')
    .eq('artist_id', goal.artist_id)
    .eq('studio_id', goal.studio_id)
    .eq('status', 'completed')
    .gte('scheduled_at', `${goal.period_start}T00:00:00Z`)
    .lte('scheduled_at', `${goal.period_end}T23:59:59Z`)

  if (error) throw new Error(error.message)
  const uniqueClients = new Set((data ?? []).map((b) => b.client_id))
  return uniqueClients.size
}

'use client'

import { useState, useCallback } from 'react'
import { UserPlus, Trash2, Users } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Slider } from '@/components/ui/slider'
import { Label } from '@/components/ui/label'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { cn } from '@/lib/utils'
import { validateSplitSum } from '@/lib/bookings/participants'
import type { ParticipantRole } from '@/lib/bookings/participants'

export interface ParticipantEntry {
  artist_id: string
  artist_name: string
  role: ParticipantRole
  split_pct: number
  notes?: string | null
}

interface ArtistOption {
  id: string
  display_name: string
}

interface BookingParticipantsFieldProps {
  participants: ParticipantEntry[]
  onChange: (participants: ParticipantEntry[]) => void
  primaryArtistId: string | null
  availableArtists: ArtistOption[]
}

const ROLE_OPTIONS: { value: ParticipantRole; label: string }[] = [
  { value: 'primary', label: 'Primary' },
  { value: 'assistant', label: 'Assistant' },
  { value: 'piercer', label: 'Piercer' },
  { value: 'apprentice', label: 'Apprentice' },
  { value: 'observer', label: 'Observer' },
]

export function BookingParticipantsField({
  participants,
  onChange,
  primaryArtistId,
  availableArtists,
}: BookingParticipantsFieldProps) {
  const [addingArtistId, setAddingArtistId] = useState<string>('')

  const { ok: splitValid, total: splitTotal } = validateSplitSum(participants)

  const usedArtistIds = new Set(participants.map((p) => p.artist_id))
  const unassignedArtists = availableArtists.filter((a) => !usedArtistIds.has(a.id))

  const updateParticipant = useCallback(
    (index: number, patch: Partial<ParticipantEntry>) => {
      const next = participants.map((p, i) => (i === index ? { ...p, ...patch } : p))

      // Enforce single primary: if we're setting this one to primary, demote the old primary
      if (patch.role === 'primary') {
        const updated = next.map((p, i) => {
          if (i !== index && p.role === 'primary') {
            return { ...p, role: 'assistant' as ParticipantRole }
          }
          return p
        })
        onChange(updated)
        return
      }

      onChange(next)
    },
    [participants, onChange],
  )

  const removeParticipant = useCallback(
    (index: number) => {
      // Can't remove the primary unless there's another participant to promote
      if (participants[index]?.role === 'primary' && participants.length > 1) {
        const next = participants.filter((_, i) => i !== index)
        // Promote first remaining to primary
        if (next[0]) next[0] = { ...next[0], role: 'primary' }
        onChange(next)
        return
      }
      if (participants.length === 1) return // Can't remove last
      onChange(participants.filter((_, i) => i !== index))
    },
    [participants, onChange],
  )

  const addParticipant = useCallback(() => {
    if (!addingArtistId) return
    const artist = availableArtists.find((a) => a.id === addingArtistId)
    if (!artist) return

    const newEntry: ParticipantEntry = {
      artist_id: artist.id,
      artist_name: artist.display_name,
      role: 'assistant',
      split_pct: 0,
    }
    onChange([...participants, newEntry])
    setAddingArtistId('')
  }, [addingArtistId, availableArtists, participants, onChange])

  const distributeEvenly = useCallback(() => {
    if (participants.length === 0) return
    const base = Math.floor(100 / participants.length)
    const remainder = 100 - base * participants.length
    const next = participants.map((p, i) => ({
      ...p,
      split_pct: i === 0 ? base + remainder : base,
    }))
    onChange(next)
  }, [participants, onChange])

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1.5">
          <Users className="h-4 w-4 text-muted-foreground" />
          <span className="text-sm font-medium text-foreground">Participants</span>
        </div>
        <div className="flex items-center gap-2">
          {participants.length > 1 && (
            <Button
              type="button"
              variant="ghost"
              size="sm"
              className="h-7 text-xs px-2"
              onClick={distributeEvenly}
            >
              Distribute evenly
            </Button>
          )}
          {/* Split total indicator */}
          <span
            className={cn(
              'text-xs font-medium tabular-nums',
              splitValid ? 'text-green-600 dark:text-green-400' : 'text-destructive',
            )}
          >
            {splitTotal.toFixed(0)}%
          </span>
        </div>
      </div>

      {/* Participant rows */}
      <div className="space-y-2">
        {participants.map((participant, index) => (
          <div
            key={participant.artist_id}
            className="rounded-lg border border-border/50 bg-muted/20 p-3 space-y-2.5"
          >
            <div className="flex items-center justify-between gap-2">
              <div className="flex items-center gap-2 min-w-0 flex-1">
                {/* Artist name */}
                <span className="text-sm font-medium truncate">{participant.artist_name}</span>
                {participant.artist_id === primaryArtistId && (
                  <span className="shrink-0 inline-flex h-4 items-center rounded-full bg-primary/10 px-1.5 text-[9px] font-medium text-primary">
                    Booking artist
                  </span>
                )}
              </div>

              {/* Role picker */}
              <Select
                value={participant.role}
                onValueChange={(val) =>
                  updateParticipant(index, { role: val as ParticipantRole })
                }
              >
                <SelectTrigger className="h-7 w-[130px] text-xs shrink-0">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {ROLE_OPTIONS.map((r) => (
                    <SelectItem key={r.value} value={r.value} className="text-xs">
                      {r.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>

              {/* Remove button — can't remove when only one participant */}
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className="h-7 w-7 shrink-0 text-muted-foreground hover:text-destructive"
                onClick={() => removeParticipant(index)}
                disabled={participants.length === 1}
                aria-label={`Remove ${participant.artist_name}`}
              >
                <Trash2 className="h-3.5 w-3.5" />
              </Button>
            </div>

            {/* Split pct slider */}
            <div className="space-y-1">
              <div className="flex items-center justify-between">
                <Label className="text-xs text-muted-foreground">Split</Label>
                <span className="text-xs font-medium tabular-nums">
                  {participant.split_pct}%
                </span>
              </div>
              <Slider
                min={0}
                max={100}
                step={1}
                value={[participant.split_pct]}
                onValueChange={([val]) =>
                  updateParticipant(index, { split_pct: val ?? 0 })
                }
                className="w-full"
                aria-label={`Split percentage for ${participant.artist_name}`}
              />
            </div>
          </div>
        ))}
      </div>

      {/* Validation message */}
      {!splitValid && participants.length > 0 && (
        <p className="text-xs text-destructive" role="alert">
          Split percentages must total 100% (currently {splitTotal.toFixed(1)}%)
        </p>
      )}

      {/* Add participant */}
      {unassignedArtists.length > 0 && (
        <div className="flex items-center gap-2">
          <Select value={addingArtistId} onValueChange={setAddingArtistId}>
            <SelectTrigger className="h-8 flex-1 text-xs">
              <SelectValue placeholder="Add artist..." />
            </SelectTrigger>
            <SelectContent>
              {unassignedArtists.map((a) => (
                <SelectItem key={a.id} value={a.id} className="text-xs">
                  {a.display_name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="h-8 shrink-0"
            onClick={addParticipant}
            disabled={!addingArtistId}
            aria-label="Add participant"
          >
            <UserPlus className="h-3.5 w-3.5" />
          </Button>
        </div>
      )}
    </div>
  )
}

