import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import {
  validateParticipantList,
  upsertBookingParticipants,
} from '@/lib/bookings/participants'
import { revalidatePath } from 'next/cache'

const ParticipantSchema = z.object({
  artist_id: z.string().uuid(),
  role: z.enum(['primary', 'assistant', 'piercer', 'apprentice', 'observer']),
  split_pct: z.number().min(0).max(100),
  notes: z.string().max(500).nullable().optional(),
})

const UpsertBodySchema = z.object({
  booking_id: z.string().uuid(),
  participants: z.array(ParticipantSchema).min(1).max(10),
})

/**
 * POST /api/booking-participants
 * Replaces all participants for a booking.
 * Validates: sum=100, no duplicates, exactly one 'primary'.
 */
export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = UpsertBodySchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { booking_id, participants } = parsed.data

  // Business logic validation
  const validationError = validateParticipantList(participants)
  if (validationError) {
    return NextResponse.json({ error: validationError }, { status: 422 })
  }

  try {
    const supabase = await createClient()

    // Verify booking belongs to this studio
    const { data: booking, error: bookingError } = await supabase
      .from('bookings')
      .select('id, studio_id')
      .eq('id', booking_id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (bookingError || !booking) {
      return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
    }

    // Verify all artist_ids belong to this studio
    const artistIds = participants.map((p) => p.artist_id)
    const { data: validArtists, error: artistError } = await supabase
      .from('artists')
      .select('id')
      .eq('studio_id', authUser.studioId)
      .in('id', artistIds)

    if (artistError) {
      logger.error({ err: artistError }, 'booking-participants: artist lookup failed')
      return NextResponse.json({ error: 'Failed to validate artists' }, { status: 500 })
    }

    if ((validArtists ?? []).length !== artistIds.length) {
      return NextResponse.json(
        { error: 'One or more artists do not belong to this studio' },
        { status: 422 },
      )
    }

    const rows = await upsertBookingParticipants(
      supabase,
      booking_id,
      authUser.studioId,
      participants.map((p) => ({
        artist_id: p.artist_id,
        role: p.role,
        split_pct: p.split_pct,
        ...(p.notes != null ? { notes: p.notes } : {}),
      })),
    )

    revalidatePath(`/appointments/${booking_id}`)
    revalidatePath('/calendar')

    return NextResponse.json({ data: rows })
  } catch (err) {
    logger.error({ err }, 'booking-participants POST failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

/**
 * GET /api/booking-participants?booking_id=xxx
 */
export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { searchParams } = new URL(request.url)
  const bookingId = searchParams.get('booking_id')

  if (!bookingId) {
    return NextResponse.json({ error: 'booking_id is required' }, { status: 400 })
  }

  try {
    const supabase = await createClient()

    // Verify booking belongs to this studio
    const { data: booking } = await supabase
      .from('bookings')
      .select('id')
      .eq('id', bookingId)
      .eq('studio_id', authUser.studioId)
      .single()

    if (!booking) {
      return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
    }

    const { data, error } = await supabase
      .from('booking_participants')
      .select('*, artists(display_name, avatar_url)')
      .eq('booking_id', bookingId)
      .order('split_pct', { ascending: false })

    if (error) {
      return NextResponse.json({ error: 'Failed to fetch participants' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? [] })
  } catch (err) {
    logger.error({ err }, 'booking-participants GET failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { upsertGoal, computeCurrentValueForGoal } from '@/lib/artists/goals'
import { logAuditAction } from '@/lib/audit'
import type { GoalRow } from '@/lib/artists/goals'

const UpsertGoalSchema = z.object({
  artist_id: z.string().uuid(),
  period_type: z.enum(['month', 'quarter', 'year']),
  period_start: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Expected YYYY-MM-DD'),
  period_end: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Expected YYYY-MM-DD'),
  metric: z.enum(['revenue', 'bookings', 'hours', 'commission', 'new_clients']),
  target_value: z.number().positive(),
  notes: z.string().max(500).nullable().optional(),
})

/**
 * GET /api/goals?artist_id=xxx&period=YYYY-MM-DD
 * Returns all goals for an artist in the period containing the given date.
 */
export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { searchParams } = new URL(request.url)
  const artistId = searchParams.get('artist_id')
  const periodStr = searchParams.get('period') // YYYY-MM-DD

  if (!artistId || !periodStr) {
    return NextResponse.json({ error: 'artist_id and period are required' }, { status: 400 })
  }

  try {
    const supabase = await createClient()

    // Verify artist belongs to studio
    const { data: artist } = await supabase
      .from('artists')
      .select('id')
      .eq('id', artistId)
      .eq('studio_id', authUser.studioId)
      .single()

    if (!artist) {
      return NextResponse.json({ error: 'Artist not found' }, { status: 404 })
    }

    const period = new Date(`${periodStr}T00:00:00Z`)
    const { fetchArtistGoalsForPeriod } = await import('@/lib/artists/goals')
    const goals = await fetchArtistGoalsForPeriod(supabase, artistId, period)

    // Compute current values for each goal
    const goalsWithProgress = await Promise.all(
      goals.map(async (goal) => {
        const current = await computeCurrentValueForGoal(supabase, goal)
        return { ...goal, current_value: current }
      }),
    )

    return NextResponse.json({ data: goalsWithProgress })
  } catch (err) {
    logger.error({ err }, 'goals GET failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

/**
 * POST /api/goals
 * Upserts a goal for an artist. Owner/admin only.
 */
export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  if (authUser.role !== 'owner' && authUser.role !== 'admin') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = UpsertGoalSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const data = parsed.data

  try {
    const supabase = await createClient()

    // Verify artist belongs to studio
    const { data: artist } = await supabase
      .from('artists')
      .select('id')
      .eq('id', data.artist_id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (!artist) {
      return NextResponse.json({ error: 'Artist not found' }, { status: 404 })
    }

    const goal: GoalRow = await upsertGoal(supabase, {
      studio_id: authUser.studioId,
      artist_id: data.artist_id,
      period_type: data.period_type,
      period_start: data.period_start,
      period_end: data.period_end,
      metric: data.metric,
      target_value: data.target_value,
      set_by: authUser.user.id,
      ...(data.notes != null ? { notes: data.notes } : {}),
    })

    await logAuditAction(
      authUser.user.id,
      'goal.set',
      { type: 'artist_goal', id: goal.id },
      { metric: data.metric, target_value: data.target_value, artist_id: data.artist_id },
      authUser.studioId,
    )

    return NextResponse.json({ data: goal }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'goals POST failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

/**
 * DELETE /api/goals?id=xxx
 * Owner/admin only.
 */
export async function DELETE(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  if (authUser.role !== 'owner' && authUser.role !== 'admin') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { searchParams } = new URL(request.url)
  const goalId = searchParams.get('id')
  if (!goalId) {
    return NextResponse.json({ error: 'id is required' }, { status: 400 })
  }

  try {
    const supabase = await createClient()

    const { error } = await supabase
      .from('artist_goals')
      .delete()
      .eq('id', goalId)
      .eq('studio_id', authUser.studioId)

    if (error) {
      return NextResponse.json({ error: 'Failed to delete goal' }, { status: 500 })
    }

    return NextResponse.json({ ok: true })
  } catch (err) {
    logger.error({ err }, 'goals DELETE failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'

/** Generates a random 8-char lowercase suffix for role_key uniqueness */
function randomSuffix(): string {
  return Math.random().toString(36).slice(2, 10).toLowerCase()
}

/** Converts a display name to a URL-safe slug */
function slugify(name: string): string {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 24)
}

const CreateCustomRoleSchema = z.object({
  display_name: z.string().min(1).max(50).trim(),
  cloned_from: z.enum(['owner', 'admin', 'artist', 'receptionist', 'guest_artist']),
  description: z.string().max(200).optional(),
})

/**
 * POST /api/custom-roles
 * Creates a new custom role by cloning permissions from a preset role.
 * Owner-only. Pro+ plan required.
 */
export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  if (authUser.role !== 'owner') {
    return NextResponse.json({ error: 'Owner role required' }, { status: 403 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = CreateCustomRoleSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { display_name, cloned_from, description } = parsed.data

  // Plan gate: custom roles require pro+
  const supabase = await createClient()
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', authUser.studioId)
    .eq('status', 'active')
    .maybeSingle()

  const plan = sub?.plan_tier ?? 'solo'
  if (plan === 'solo' || plan === 'studio') {
    return NextResponse.json(
      { error: 'Custom roles require Pro or Enterprise plan' },
      { status: 403 },
    )
  }

  // Generate unique role_key
  const slug = slugify(display_name)
  const suffix = randomSuffix()
  const role_key = `custom:${slug}_${suffix}`

  try {
    // Use service-role to bypass RLS for role_permissions copy
    const serviceClient = createServiceRoleClient()

    // Insert the custom role record
    const { data: newRole, error: roleError } = await serviceClient
      .from('studio_custom_roles')
      .insert({
        studio_id: authUser.studioId,
        role_key,
        display_name,
        cloned_from,
        ...(description != null ? { description } : {}),
        created_by: authUser.user.id,
      })
      .select()
      .single()

    if (roleError) {
      logger.error({ err: roleError }, 'custom-roles: insert failed')
      return NextResponse.json({ error: 'Failed to create custom role' }, { status: 500 })
    }

    // Copy permission rows from the source role
    const { data: sourcePerms, error: permsError } = await serviceClient
      .from('role_permissions')
      .select('permission_key, granted')
      .eq('role', cloned_from)

    if (permsError) {
      logger.error({ err: permsError }, 'custom-roles: source perms fetch failed')
      // Role was created — return it but warn about missing perms
      return NextResponse.json({ data: newRole, warning: 'Permissions could not be copied' })
    }

    if ((sourcePerms ?? []).length > 0) {
      const newPerms = (sourcePerms ?? []).map((p) => ({
        role: role_key,
        permission_key: p.permission_key,
        granted: p.granted,
      }))

      const { error: insertPermsError } = await serviceClient
        .from('role_permissions')
        .insert(newPerms)

      if (insertPermsError) {
        logger.error({ err: insertPermsError }, 'custom-roles: permission copy failed')
      }
    }

    await logAuditAction(
      authUser.user.id,
      'custom_role.created',
      { type: 'studio_custom_role', id: newRole.id },
      { role_key, cloned_from, display_name },
      authUser.studioId,
    )

    return NextResponse.json({ data: newRole }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'custom-roles POST failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

/**
 * GET /api/custom-roles
 * Returns all custom roles for the current studio.
 */
export async function GET(_request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  if (authUser.role !== 'owner' && authUser.role !== 'admin') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  try {
    const supabase = await createClient()
    const { data, error } = await supabase
      .from('studio_custom_roles')
      .select('*')
      .eq('studio_id', authUser.studioId)
      .order('created_at', { ascending: true })

    if (error) {
      return NextResponse.json({ error: 'Failed to fetch custom roles' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? [] })
  } catch (err) {
    logger.error({ err }, 'custom-roles GET failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'

const DeleteBodySchema = z.object({
  reassign_to: z.string().min(1).optional(),
})

/**
 * DELETE /api/custom-roles/[roleKey]
 * Deletes a custom role. Blocked if users are assigned unless reassign_to provided.
 * Owner-only.
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ roleKey: string }> },
) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  if (authUser.role !== 'owner') {
    return NextResponse.json({ error: 'Owner role required' }, { status: 403 })
  }

  const { roleKey } = await params

  // Validate role key format
  if (!roleKey.startsWith('custom:')) {
    return NextResponse.json({ error: 'Only custom roles can be deleted' }, { status: 400 })
  }

  let body: unknown = {}
  try {
    const text = await request.text()
    if (text) body = JSON.parse(text)
  } catch {
    // Body is optional for DELETE
  }

  const parsed = DeleteBodySchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { reassign_to } = parsed.data

  try {
    const supabase = await createClient()
    const serviceClient = createServiceRoleClient()

    // Verify the custom role belongs to this studio
    const { data: customRole, error: roleError } = await supabase
      .from('studio_custom_roles')
      .select('id, role_key')
      .eq('role_key', roleKey)
      .eq('studio_id', authUser.studioId)
      .single()

    if (roleError || !customRole) {
      return NextResponse.json({ error: 'Custom role not found' }, { status: 404 })
    }

    // Check if any studio members are assigned this role
    const { count: assignedCount } = await supabase
      .from('studio_members')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', authUser.studioId)
      .eq('role', roleKey)
      .is('deactivated_at', null)

    if ((assignedCount ?? 0) > 0) {
      if (!reassign_to) {
        return NextResponse.json(
          {
            error: `${assignedCount} member(s) are assigned this role. Provide reassign_to to proceed.`,
            assigned_count: assignedCount,
          },
          { status: 409 },
        )
      }

      // Reassign members to the target role
      const { error: reassignError } = await serviceClient
        .from('studio_members')
        .update({ role: reassign_to })
        .eq('studio_id', authUser.studioId)
        .eq('role', roleKey)

      if (reassignError) {
        logger.error({ err: reassignError }, 'custom-roles: reassign failed')
        return NextResponse.json({ error: 'Failed to reassign members' }, { status: 500 })
      }
    }

    // Delete role_permissions rows for this role_key
    await serviceClient
      .from('role_permissions')
      .delete()
      .eq('role', roleKey)

    // Delete the custom role record
    const { error: deleteError } = await serviceClient
      .from('studio_custom_roles')
      .delete()
      .eq('id', customRole.id)

    if (deleteError) {
      logger.error({ err: deleteError }, 'custom-roles: delete failed')
      return NextResponse.json({ error: 'Failed to delete custom role' }, { status: 500 })
    }

    await logAuditAction(
      authUser.user.id,
      'custom_role.deleted',
      { type: 'studio_custom_role', id: customRole.id },
      { role_key: roleKey, reassign_to: reassign_to ?? null },
      authUser.studioId,
    )

    return NextResponse.json({ ok: true })
  } catch (err) {
    logger.error({ err }, 'custom-roles DELETE failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use client'

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { Plus, Target, Trash2, Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Progress } from '@/components/ui/progress'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog'
import { Label } from '@/components/ui/label'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Skeleton } from '@/components/ui/skeleton'
import { EmptyState } from '@/components/shared/EmptyState'
import { toast } from 'sonner'
import { format, startOfMonth, endOfMonth } from 'date-fns'
import { cn } from '@/lib/utils'

interface GoalRow {
  id: string
  metric: 'revenue' | 'bookings' | 'hours' | 'commission' | 'new_clients'
  period_type: 'month' | 'quarter' | 'year'
  period_start: string
  period_end: string
  target_value: number
  current_value: number
  notes: string | null
}

interface ArtistGoalsPanelProps {
  artistId: string
  canManage: boolean
}

const METRIC_LABELS: Record<GoalRow['metric'], string> = {
  revenue:     'Revenue',
  bookings:    'Bookings',
  hours:       'Hours worked',
  commission:  'Commission',
  new_clients: 'New clients',
}

const METRIC_FORMAT: Record<GoalRow['metric'], (v: number) => string> = {
  revenue:     (v) => `$${(v / 100).toLocaleString()}`,
  bookings:    (v) => String(v),
  hours:       (v) => `${v}h`,
  commission:  (v) => `$${(v / 100).toLocaleString()}`,
  new_clients: (v) => String(v),
}

function progressColor(pct: number): string {
  if (pct >= 80) return 'bg-green-500'
  if (pct >= 50) return 'bg-amber-500'
  return 'bg-destructive'
}

export function ArtistGoalsPanel({ artistId, canManage }: ArtistGoalsPanelProps) {
  const qc = useQueryClient()
  const now = new Date()
  const periodStr = format(startOfMonth(now), 'yyyy-MM-dd')

  const [dialogOpen, setDialogOpen] = useState(false)
  const [metric, setMetric] = useState<GoalRow['metric']>('revenue')
  const [periodType, setPeriodType] = useState<GoalRow['period_type']>('month')
  const [targetValue, setTargetValue] = useState('')
  const [notes, setNotes] = useState('')

  const { data, isLoading } = useQuery<{ data: GoalRow[] }>({
    queryKey: ['artist-goals', artistId, periodStr],
    queryFn: async () => {
      const res = await fetch(`/api/goals?artist_id=${artistId}&period=${periodStr}`)
      if (!res.ok) throw new Error('Failed to fetch goals')
      return res.json() as Promise<{ data: GoalRow[] }>
    },
  })

  const goals = data?.data ?? []

  const createMutation = useMutation({
    mutationFn: async () => {
      const start = format(startOfMonth(now), 'yyyy-MM-dd')
      const end = format(endOfMonth(now), 'yyyy-MM-dd')

      const res = await fetch('/api/goals', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          artist_id: artistId,
          period_type: periodType,
          period_start: start,
          period_end: end,
          metric,
          target_value: Number(targetValue),
          ...(notes ? { notes } : {}),
        }),
      })
      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Failed to set goal')
      }
    },
    onSuccess: () => {
      void qc.invalidateQueries({ queryKey: ['artist-goals', artistId] })
      toast.success('Goal set')
      setDialogOpen(false)
      setTargetValue('')
      setNotes('')
    },
    onError: (err: Error) => toast.error(err.message),
  })

  const deleteMutation = useMutation({
    mutationFn: async (goalId: string) => {
      const res = await fetch(`/api/goals?id=${goalId}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed to delete goal')
    },
    onSuccess: () => {
      void qc.invalidateQueries({ queryKey: ['artist-goals', artistId] })
      toast.success('Goal removed')
    },
    onError: (err: Error) => toast.error(err.message),
  })

  return (
    <Card className="shadow-soft">
      <CardHeader className="flex flex-row items-center justify-between pb-3">
        <div className="flex items-center gap-2">
          <Target className="h-4 w-4 text-muted-foreground" />
          <CardTitle className="text-base">Goals — {format(now, 'MMMM yyyy')}</CardTitle>
        </div>
        {canManage && (
          <Button
            size="sm"
            variant="outline"
            className="h-7 text-xs"
            onClick={() => setDialogOpen(true)}
          >
            <Plus className="h-3.5 w-3.5 mr-1" />
            Set goal
          </Button>
        )}
      </CardHeader>

      <CardContent>
        {isLoading ? (
          <div className="space-y-3">
            {Array.from({ length: 3 }).map((_, i) => (
              <Skeleton key={i} className="h-14 rounded-lg" />
            ))}
          </div>
        ) : goals.length === 0 ? (
          <EmptyState
            icon={Target}
            title="No goals set"
            description={canManage ? 'Set monthly goals to track progress.' : 'No goals set for this period.'}
            {...(canManage ? {
              action: { label: 'Set first goal', onClick: () => setDialogOpen(true) },
            } : {})}
          />
        ) : (
          <div className="space-y-3">
            {goals.map((goal) => {
              const pct = goal.target_value > 0
                ? Math.min(100, (goal.current_value / goal.target_value) * 100)
                : 0
              const fmt = METRIC_FORMAT[goal.metric]
              return (
                <div key={goal.id} className="space-y-1.5">
                  <div className="flex items-center justify-between text-sm">
                    <span className="font-medium">{METRIC_LABELS[goal.metric]}</span>
                    <div className="flex items-center gap-2">
                      <span className="tabular-nums text-xs text-muted-foreground">
                        {fmt(goal.current_value)} / {fmt(goal.target_value)}
                      </span>
                      <span
                        className={cn(
                          'text-[10px] font-medium tabular-nums',
                          pct >= 80 ? 'text-green-600 dark:text-green-400' : pct >= 50 ? 'text-amber-600' : 'text-destructive',
                        )}
                      >
                        {pct.toFixed(0)}%
                      </span>
                      {canManage && (
                        <button
                          type="button"
                          className="text-muted-foreground/40 hover:text-destructive transition-colors"
                          onClick={() => deleteMutation.mutate(goal.id)}
                          disabled={deleteMutation.isPending}
                          aria-label={`Delete ${METRIC_LABELS[goal.metric]} goal`}
                        >
                          <Trash2 className="h-3.5 w-3.5" />
                        </button>
                      )}
                    </div>
                  </div>
                  <div className="relative h-1.5 w-full overflow-hidden rounded-full bg-muted">
                    <div
                      className={cn('h-full rounded-full transition-all duration-500', progressColor(pct))}
                      style={{ width: `${pct}%` }}
                      role="progressbar"
                      aria-valuenow={pct}
                      aria-valuemin={0}
                      aria-valuemax={100}
                    />
                  </div>
                  {goal.notes && (
                    <p className="text-[10px] text-muted-foreground">{goal.notes}</p>
                  )}
                </div>
              )
            })}
          </div>
        )}
      </CardContent>

      {/* Set goal dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Set goal</DialogTitle>
          </DialogHeader>

          <div className="space-y-4 py-2">
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <Label>Metric</Label>
                <Select value={metric} onValueChange={(v) => setMetric(v as GoalRow['metric'])}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {(Object.entries(METRIC_LABELS) as [GoalRow['metric'], string][]).map(([k, v]) => (
                      <SelectItem key={k} value={k}>{v}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-1.5">
                <Label>Period</Label>
                <Select
                  value={periodType}
                  onValueChange={(v) => setPeriodType(v as GoalRow['period_type'])}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="month">Month</SelectItem>
                    <SelectItem value="quarter">Quarter</SelectItem>
                    <SelectItem value="year">Year</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="space-y-1.5">
              <Label>
                Target value
                {metric === 'revenue' || metric === 'commission'
                  ? ' (in dollars)'
                  : metric === 'hours'
                  ? ' (hours)'
                  : ''}
              </Label>
              <Input
                type="number"
                min="1"
                step="1"
                value={targetValue}
                onChange={(e) => setTargetValue(e.target.value)}
                placeholder="e.g. 5000"
              />
            </div>

            <div className="space-y-1.5">
              <Label>Notes (optional)</Label>
              <Textarea
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="Additional context..."
                className="resize-none min-h-[60px] text-sm"
                maxLength={500}
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setDialogOpen(false)}>
              Cancel
            </Button>
            <Button
              onClick={() => createMutation.mutate()}
              disabled={!targetValue || Number(targetValue) <= 0 || createMutation.isPending}
            >
              {createMutation.isPending ? (
                <Loader2 className="h-4 w-4 mr-2 animate-spin" aria-hidden="true" />
              ) : null}
              Set goal
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </Card>
  )
}

'use client'

import { useQuery } from '@tanstack/react-query'
import { Trophy } from 'lucide-react'
