import type { ArtistPerformanceSummaryRow } from '@/lib/artists/performance-types'

interface LeaderRow {
  artist_id: string
  display_name: string
  avatar_url: string | null
  revenue_cents: number
}

const MEDAL_COLORS = ['text-yellow-500', 'text-slate-400', 'text-amber-600']
const MEDAL_LABELS = ['1st', '2nd', '3rd']

function getInitials(name: string): string {
  return name.split(' ').slice(0, 2).map((n) => n[0]?.toUpperCase() ?? '').join('')
}

interface LeaderboardCardProps {
  studioId: string
}

export function LeaderboardCard({ studioId }: LeaderboardCardProps) {
  const now = new Date()
  const periodMonth = format(startOfMonth(now), 'yyyy-MM-dd')

  const { data, isLoading } = useQuery<LeaderRow[]>({
    queryKey: ['leaderboard', studioId, periodMonth],
    queryFn: async () => {
      const res = await fetch(
        `/api/leaderboard?studio_id=${studioId}&period_month=${periodMonth}`,
      )
      if (!res.ok) throw new Error('Failed to fetch leaderboard')
      const json = await res.json() as { data: LeaderRow[] }
      return json.data ?? []
