import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { rawQuery } from '@/lib/supabase/raw-query'
import type { ArtistPerformanceSummaryRow } from '@/lib/artists/performance-types'

interface ArtistRow {
  id: string
  display_name: string
  avatar_url: string | null
}

/**
 * GET /api/leaderboard?studio_id=xxx&period_month=YYYY-MM-DD
 * Returns top 5 artists by revenue for the given month.
 * Owner/admin/receptionist only.
 */
export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  // Artists cannot see the leaderboard
  if (authUser.role === 'artist' || authUser.role === 'guest_artist') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { searchParams } = new URL(request.url)
  const periodMonth = searchParams.get('period_month')

  if (!periodMonth) {
    return NextResponse.json({ error: 'period_month is required' }, { status: 400 })
  }

  try {
    const supabase = await createClient()

    // Query performance view for the studio + month
    const { data: summaries, error: summaryError } = await rawQuery<ArtistPerformanceSummaryRow>(
      supabase,
      'artist_performance_summary',
    )
      .select('artist_id, studio_id, period_month, revenue_cents')
      .eq('studio_id', authUser.studioId)
      .eq('period_month', periodMonth)
      .order('revenue_cents', { ascending: false })
      .limit(5)

    if (summaryError) {
      logger.error({ err: summaryError }, 'leaderboard: view query failed')
      return NextResponse.json({ error: 'Failed to fetch leaderboard' }, { status: 500 })
    }

    const rows = summaries ?? []
    if (rows.length === 0) {
      return NextResponse.json({ data: [] })
    }

    // Fetch artist display names
    const artistIds = rows.map((r) => r.artist_id)
    const { data: artists, error: artistError } = await supabase
      .from('artists')
      .select('id, display_name, avatar_url')
      .in('id', artistIds)

    if (artistError) {
      logger.error({ err: artistError }, 'leaderboard: artist fetch failed')
      return NextResponse.json({ error: 'Failed to fetch artist info' }, { status: 500 })
    }

    const artistMap = new Map<string, ArtistRow>(
      (artists ?? []).map((a) => [a.id, a as ArtistRow]),
    )

    const leaderboard = rows.map((r) => {
      const artist = artistMap.get(r.artist_id)
      return {
        artist_id: r.artist_id,
        display_name: artist?.display_name ?? 'Unknown',
        avatar_url: artist?.avatar_url ?? null,
        revenue_cents: r.revenue_cents,
      }
    })

    return NextResponse.json({ data: leaderboard })
  } catch (err) {
    logger.error({ err }, 'leaderboard GET failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use client'

import { useQuery } from '@tanstack/react-query'
import {
  CalendarDays,
  DollarSign,
  Clock,
  Target,
  ChevronRight,
} from 'lucide-react'
import Link from 'next/link'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import { Typography } from '@/components/ui/typography'
import { EmptyState } from '@/components/shared/EmptyState'
import { formatCurrency, cn } from '@/lib/utils'
import { format, startOfMonth, endOfMonth, addDays } from 'date-fns'

interface ArtistTodayProps {
  firstName: string
  studioId: string
  artistId: string
  artistEarningsToday: number
}

interface TodayBooking {
  id: string
  scheduled_at: string
  status: string
  clientName: string
  serviceName: string
  price_cents: number
}

interface GoalRow {
  id: string
  metric: string
  target_value: number
  current_value: number
}

const STATUS_CLASS: Record<string, string> = {
  pending:     'bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-300',
  confirmed:   'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300',
  in_progress: 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300',
  completed:   'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300',
  cancelled:   'bg-muted text-muted-foreground',
  no_show:     'bg-destructive/10 text-destructive',
}

function formatDate(): string {
  return new Date().toLocaleDateString('en-US', {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
  })
}

export function ArtistTodayDashboard({
  firstName,
  studioId,
  artistId,
  artistEarningsToday,
}: ArtistTodayProps) {
  const now = new Date()
  const periodStr = format(startOfMonth(now), 'yyyy-MM-dd')

  // Today's bookings for this artist
  const todayQuery = useQuery<{ data: TodayBooking[] }>({
    queryKey: ['today-agenda', studioId, artistId],
    queryFn: async () => {
      const res = await fetch(`/api/today?artist_id=${artistId}`)
      if (!res.ok) throw new Error('Failed to fetch today agenda')
      return res.json() as Promise<{ data: TodayBooking[] }>
    },
  })

  // Upcoming 7 days
  const upcomingQuery = useQuery<{ data: TodayBooking[] }>({
    queryKey: ['upcoming-bookings', artistId],
    queryFn: async () => {
      const from = format(addDays(now, 1), 'yyyy-MM-dd')
      const to = format(addDays(now, 7), 'yyyy-MM-dd')
      const res = await fetch(
        `/api/bookings?artist_id=${artistId}&from=${from}T00:00:00Z&to=${to}T23:59:59Z&per_page=20`,
      )
      if (!res.ok) throw new Error('Failed to fetch upcoming')
      return res.json() as Promise<{ data: TodayBooking[] }>
    },
  })

  // Goals for this month
  const goalsQuery = useQuery<{ data: GoalRow[] }>({
    queryKey: ['artist-goals', artistId, periodStr],
    queryFn: async () => {
      const res = await fetch(`/api/goals?artist_id=${artistId}&period=${periodStr}`)
      if (!res.ok) throw new Error('Failed to fetch goals')
      return res.json() as Promise<{ data: GoalRow[] }>
    },
  })

  const todayBookings = todayQuery.data?.data ?? []
  const upcomingBookings = upcomingQuery.data?.data ?? []
  const goals = goalsQuery.data?.data ?? []

  const mtdGoal = goals.find((g) => g.metric === 'revenue')
  const mtdPct = mtdGoal && mtdGoal.target_value > 0
    ? Math.min(100, (mtdGoal.current_value / mtdGoal.target_value) * 100)
    : null

  return (
    <div className="min-h-full bg-[var(--color-page-bg)]">
      <div className="mx-auto max-w-[1200px] space-y-6 px-4 pb-10 pt-6 sm:px-6 lg:px-8">

        {/* Header */}
        <div>
          <Typography variant="h1" className="text-foreground">
            Your day,{' '}
            <span className="text-primary">{firstName}</span>
          </Typography>
          <p className="mt-0.5 text-sm text-muted-foreground">{formatDate()}</p>
        </div>

        {/* KPI row */}
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
          <Card className="shadow-soft">
            <CardContent className="p-4">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-xs text-muted-foreground uppercase tracking-wide font-medium mb-1">
                    Earned today
                  </p>
                  <p className="text-2xl font-bold tabular-nums">
                    {formatCurrency(artistEarningsToday)}
                  </p>
                </div>
                <DollarSign className="h-8 w-8 text-primary/30" aria-hidden="true" />
              </div>
            </CardContent>
          </Card>

          <Card className="shadow-soft">
            <CardContent className="p-4">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-xs text-muted-foreground uppercase tracking-wide font-medium mb-1">
                    Today&apos;s bookings
                  </p>
                  <p className="text-2xl font-bold tabular-nums">
                    {todayQuery.isLoading ? '—' : todayBookings.length}
                  </p>
                </div>
                <CalendarDays className="h-8 w-8 text-primary/30" aria-hidden="true" />
              </div>
            </CardContent>
          </Card>

          {mtdGoal ? (
            <Card className="shadow-soft">
              <CardContent className="p-4">
                <p className="text-xs text-muted-foreground uppercase tracking-wide font-medium mb-1">
                  MTD goal
                </p>
                <div className="flex items-center gap-2">
                  <p className="text-2xl font-bold tabular-nums">
                    {mtdPct?.toFixed(0) ?? '—'}%
                  </p>
                  <Target className="h-5 w-5 text-primary/40" aria-hidden="true" />
                </div>
                <div className="mt-2 h-1.5 w-full overflow-hidden rounded-full bg-muted">
                  <div
                    className={cn(
                      'h-full rounded-full transition-all',
                      (mtdPct ?? 0) >= 80
                        ? 'bg-green-500'
                        : (mtdPct ?? 0) >= 50
                        ? 'bg-amber-500'
                        : 'bg-destructive',
                    )}
                    style={{ width: `${mtdPct ?? 0}%` }}
                    role="progressbar"
                    aria-valuenow={mtdPct ?? 0}
                    aria-valuemin={0}
                    aria-valuemax={100}
                  />
                </div>
              </CardContent>
            </Card>
          ) : (
            <Card className="shadow-soft">
              <CardContent className="p-4">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-xs text-muted-foreground uppercase tracking-wide font-medium mb-1">
                      Upcoming
                    </p>
                    <p className="text-2xl font-bold tabular-nums">
                      {upcomingQuery.isLoading ? '—' : upcomingBookings.length}
                    </p>
                    <p className="text-xs text-muted-foreground">next 7 days</p>
                  </div>
                  <Clock className="h-8 w-8 text-primary/30" aria-hidden="true" />
                </div>
              </CardContent>
            </Card>
          )}
        </div>

        <div className="grid grid-cols-1 gap-4 lg:grid-cols-2">
          {/* Today's appointments */}
          <Card className="shadow-soft">
            <CardHeader className="flex flex-row items-center justify-between pb-3">
              <CardTitle className="text-base">Today&apos;s appointments</CardTitle>
              <Link
                href="/calendar"
                className="text-xs text-primary hover:underline flex items-center gap-0.5"
              >
                View calendar
                <ChevronRight className="h-3 w-3" />
              </Link>
            </CardHeader>
            <CardContent>
              {todayQuery.isLoading ? (
                <div className="space-y-2">
                  {Array.from({ length: 3 }).map((_, i) => (
                    <Skeleton key={i} className="h-14 rounded-lg" />
                  ))}
                </div>
              ) : todayBookings.length === 0 ? (
                <EmptyState
                  icon={CalendarDays}
                  title="Nothing scheduled today"
                  description="Enjoy the free time."
                />
              ) : (
                <div className="space-y-2">
                  {todayBookings.map((b) => (
                    <Link
                      key={b.id}
                      href={`/appointments/${b.id}`}
                      className="flex items-center justify-between rounded-lg border border-border/50 bg-muted/20 px-3 py-2.5 hover:bg-muted/40 transition-colors"
                    >
                      <div className="min-w-0">
                        <p className="text-sm font-medium truncate">{b.clientName}</p>
                        <p className="text-xs text-muted-foreground truncate">{b.serviceName}</p>
                      </div>
                      <div className="flex items-center gap-2 shrink-0 ml-2">
                        <span className="text-xs text-muted-foreground tabular-nums">
                          {new Date(b.scheduled_at).toLocaleTimeString('en-US', {
                            hour: '2-digit',
                            minute: '2-digit',
                          })}
                        </span>
                        <Badge
                          className={cn(
                            'text-[9px] h-4 px-1.5 capitalize',
                            STATUS_CLASS[b.status] ?? '',
                          )}
                          variant="secondary"
                        >
                          {b.status.replace('_', ' ')}
                        </Badge>
                      </div>
                    </Link>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>

          {/* Upcoming 7 days */}
          <Card className="shadow-soft">
            <CardHeader className="flex flex-row items-center justify-between pb-3">
              <CardTitle className="text-base">Next 7 days</CardTitle>
            </CardHeader>
            <CardContent>
              {upcomingQuery.isLoading ? (
                <div className="space-y-2">
                  {Array.from({ length: 4 }).map((_, i) => (
                    <Skeleton key={i} className="h-12 rounded-lg" />
                  ))}
                </div>
              ) : upcomingBookings.length === 0 ? (
                <p className="text-sm text-muted-foreground text-center py-4">
                  No upcoming bookings in the next 7 days.
                </p>
              ) : (
                <div className="space-y-1.5">
                  {upcomingBookings.slice(0, 8).map((b) => (
                    <Link
                      key={b.id}
                      href={`/appointments/${b.id}`}
                      className="flex items-center justify-between rounded-lg px-2.5 py-2 hover:bg-muted/30 transition-colors"
                    >
                      <div className="min-w-0">
                        <p className="text-sm font-medium truncate">{b.clientName}</p>
                        <p className="text-xs text-muted-foreground">
                          {new Date(b.scheduled_at).toLocaleDateString('en-US', {
                            weekday: 'short',
                            month: 'short',
                            day: 'numeric',
                          })}
                        </p>
                      </div>
                      <span className="text-xs tabular-nums text-muted-foreground">
                        {formatCurrency(b.price_cents)}
                      </span>
                    </Link>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </div>

        {/* Goals section */}
        {goals.length > 0 && (
          <Card className="shadow-soft">
            <CardHeader className="pb-3">
              <div className="flex items-center gap-2">
                <Target className="h-4 w-4 text-muted-foreground" />
                <CardTitle className="text-base">
                  My goals — {format(now, 'MMMM yyyy')}
                </CardTitle>
              </div>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                {goals.map((goal) => {
                  const pct = goal.target_value > 0
                    ? Math.min(100, (goal.current_value / goal.target_value) * 100)
                    : 0
                  return (
                    <div key={goal.id} className="space-y-1">
                      <div className="flex items-center justify-between text-sm">
                        <span className="capitalize">{goal.metric.replace('_', ' ')}</span>
                        <span className="tabular-nums text-xs text-muted-foreground">
                          {pct.toFixed(0)}%
                        </span>
                      </div>
                      <div className="h-1.5 w-full overflow-hidden rounded-full bg-muted">
                        <div
                          className={cn(
                            'h-full rounded-full transition-all',
                            pct >= 80 ? 'bg-green-500' : pct >= 50 ? 'bg-amber-500' : 'bg-destructive',
                          )}
                          style={{ width: `${pct}%` }}
                          role="progressbar"
                          aria-valuenow={pct}
                          aria-valuemin={0}
                          aria-valuemax={100}
                        />
                      </div>
                    </div>
                  )
                })}
              </div>
            </CardContent>
          </Card>
        )}

      </div>
    </div>
  )
}

