input.content:
'use client'

import { useState } from 'react'
import { Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@/components/ui/dialog'
import { Label } from '@/components/ui/label'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { toast } from 'sonner'

type PresetRole = 'owner' | 'admin' | 'artist' | 'receptionist' | 'guest_artist'

const PRESET_ROLE_LABELS: Record<PresetRole, string> = {
  owner: 'Owner',
  admin: 'Admin',
  artist: 'Artist',
  receptionist: 'Receptionist',
  guest_artist: 'Guest Artist',
}

// Cloning 'owner' or 'admin' is intentionally allowed — permissions can be pruned after creation
const CLONEABLE_ROLES: PresetRole[] = ['admin', 'artist', 'receptionist', 'guest_artist']

interface CloneRoleDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onCreated: (roleKey: string, displayName: string, clonedFrom: PresetRole) => void
}

export function CloneRoleDialog({ open, onOpenChange, onCreated }: CloneRoleDialogProps) {
  const [displayName, setDisplayName] = useState('')
  const [clonedFrom, setClonedFrom] = useState<PresetRole>('artist')
  const [description, setDescription] = useState('')
  const [loading, setLoading] = useState(false)

  const handleSubmit = async () => {
    if (!displayName.trim()) {
      toast.error('Role name is required')
      return
    }

    setLoading(true)
    try {
      const res = await fetch('/api/custom-roles', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          display_name: displayName.trim(),
          cloned_from: clonedFrom,
          ...(description.trim() ? { description: description.trim() } : {}),
        }),
      })

      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Failed to create custom role')
      }

      const { data } = await res.json() as { data: { role_key: string } }
      toast.success(`Custom role "${displayName.trim()}" created`)
      onCreated(data.role_key, displayName.trim(), clonedFrom)
      setDisplayName('')
      setDescription('')
      setClonedFrom('artist')
      onOpenChange(false)
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : 'Failed to create custom role'
      toast.error(message)
    } finally {
      setLoading(false)
    }
  }

  // Slug preview
  const slugPreview = displayName.trim()
    ? `custom:${displayName.toLowerCase().replace(/[^a-z0-9]+/g, '_').slice(0, 24)}_••••••••`
    : ''

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Create custom role</DialogTitle>
          <DialogDescription>
            Clone a preset role and customize its permissions independently.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          <div className="space-y-1.5">
            <Label htmlFor="clone-from">Clone from</Label>
            <Select
              value={clonedFrom}
              onValueChange={(v) => setClonedFrom(v as PresetRole)}
            >
              <SelectTrigger id="clone-from">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {CLONEABLE_ROLES.map((r) => (
                  <SelectItem key={r} value={r}>
                    {PRESET_ROLE_LABELS[r]}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <p className="text-[11px] text-muted-foreground">
              All permissions from this role will be copied to the new role.
            </p>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="role-name">Role name</Label>
            <Input
              id="role-name"
              value={displayName}
              onChange={(e) => setDisplayName(e.target.value)}
              placeholder="e.g. Apprentice, Senior Artist, Front Desk"
              maxLength={50}
              autoFocus
            />
            {slugPreview && (
              <p className="text-[10px] font-mono text-muted-foreground/60 truncate">
                {slugPreview}
              </p>
            )}
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="role-description">Description (optional)</Label>
            <Textarea
              id="role-description"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="What does this role do?"
              className="resize-none min-h-[60px] text-sm"
              maxLength={200}
            />
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button
            onClick={() => void handleSubmit()}
            disabled={!displayName.trim() || loading}
          >
            {loading ? (
              <Loader2 className="h-4 w-4 mr-2 animate-spin" aria-hidden="true" />
            ) : null}
            Create role
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { TodayClient } from '@/components/today/TodayClient'
import { ArtistTodayDashboard } from '@/components/today/ArtistTodayDashboard'
import type { GettingStartedCounts } from '@/components/dashboard/GettingStartedCard'
import { getArtistIdForUser, getArtistEarningsToday } from '@/lib/today/queries'
import type { Database } from '@/lib/supabase/types'

export const metadata: Metadata = {
  title: 'Today — InkOS',
}

type StudioRole = Database['public']['Tables']['studio_members']['Row']['role']

export default async function TodayPage() {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  const [profileResult, memberResult] = await Promise.all([
    supabase
      .from('profiles')
      .select('full_name')
      .eq('id', user.id)
      .single(),
    supabase
      .from('studio_members')
      .select('studio_id, role, studios(name)')
      .eq('user_id', user.id)
      .is('deactivated_at', null)
      .order('created_at', { ascending: true })
      .limit(1)
      .single(),
  ])

  const firstName = profileResult.data?.full_name?.split(' ')[0] ?? 'there'
  const studioName =
    (memberResult.data?.studios as { name: string } | null)?.name ?? 'My Studio'
  const hasStudio = !!memberResult.data?.studio_id
  const studioId = memberResult.data?.studio_id
  const role: StudioRole = memberResult.data?.role ?? 'owner'

  let gettingStartedCounts: GettingStartedCounts = {
    services: 0,
    artists: 0,
    schedules: 0,
    bookings: 0,
    bookingPageConfigured: false,
  }

  let ownArtistId: string | null = null
  let artistEarningsToday = 0

  if (studioId) {
    const [servicesRes, artistsRes, schedulesRes, bookingsRes, bpRes] = await Promise.all([
      supabase
        .from('services')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
      supabase
        .from('artists')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
      supabase
        .from('artist_schedules')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
      supabase
        .from('bookings')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
      supabase
        .from('booking_page_settings')
        .select('studio_id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
    ])

    gettingStartedCounts = {
      services: servicesRes.count ?? 0,
      artists: artistsRes.count ?? 0,
      schedules: schedulesRes.count ?? 0,
      bookings: bookingsRes.count ?? 0,
      bookingPageConfigured: (bpRes.count ?? 0) > 0,
    }

    if (role === 'artist' || role === 'guest_artist') {
      ownArtistId = await getArtistIdForUser(supabase, studioId, user.id)
      if (ownArtistId) {
        artistEarningsToday = await getArtistEarningsToday(supabase, studioId, ownArtistId)
      }
    }
  }

  // S19: artist and guest_artist roles see their personal artist dashboard
  if ((role === 'artist' || role === 'guest_artist') && studioId && ownArtistId) {
    return (
      <ArtistTodayDashboard
        firstName={firstName}
        studioId={studioId}
        artistId={ownArtistId}
        artistEarningsToday={artistEarningsToday}
      />
    )
  }

  return (
    <TodayClient
      firstName={firstName}
