// ── Bookings During Engagement Tab ─────────────────────────────────────────────

interface EngagementBooking {
  id: string
  scheduled_at: string
  status: string
  price_cents: number
  clients: { first_name: string; last_name: string | null } | null
  services: { name: string } | null
}

function EngagementBookingsTab({ id }: { id: string }) {
  const { data, isLoading } = useQuery({
    queryKey: [...queryKeys.guestArtists.engagement(id), 'bookings'],
    queryFn: async () => {
      const res = await fetch(`/api/guest-artists/${id}/engagement-bookings`)
      if (!res.ok) throw new Error('Failed to fetch engagement bookings')
      return res.json() as Promise<{
        data: EngagementBooking[]
        total_revenue_cents: number
        total_commission_cents: number
      }>
    },
  })

  if (isLoading) {
    return (
      <div className="space-y-2">
        {Array.from({ length: 5 }).map((_, i) => (
          <Skeleton key={i} className="h-12 rounded-lg" />
        ))}
      </div>
    )
  }

  const bookings = data?.data ?? []
  const totalRevenue = data?.total_revenue_cents ?? 0
  const totalCommission = data?.total_commission_cents ?? 0

  return (
    <div className="space-y-4">
      {/* Summary KPIs */}
      <div className="grid grid-cols-2 gap-3">
        <div className="rounded-lg border border-border/50 bg-muted/20 p-3">
          <p className="text-xs text-muted-foreground uppercase tracking-wide font-medium mb-0.5">
            Revenue generated
          </p>
          <p className="text-lg font-bold tabular-nums">
            ${(totalRevenue / 100).toLocaleString()}
          </p>
        </div>
        <div className="rounded-lg border border-border/50 bg-muted/20 p-3">
          <p className="text-xs text-muted-foreground uppercase tracking-wide font-medium mb-0.5">
            Artist earnings
          </p>
          <p className="text-lg font-bold tabular-nums">
            ${(totalCommission / 100).toLocaleString()}
          </p>
        </div>
      </div>

      {bookings.length === 0 ? (
        <p className="text-sm text-muted-foreground text-center py-6">
          No bookings found during this engagement period.
        </p>
      ) : (
        <div className="rounded-lg border border-border/50 overflow-hidden">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-muted/40 border-b border-border/50">
                <th className="px-4 py-2.5 text-left font-medium text-muted-foreground">Client</th>
                <th className="px-4 py-2.5 text-left font-medium text-muted-foreground">Service</th>
                <th className="px-4 py-2.5 text-left font-medium text-muted-foreground">Date</th>
                <th className="px-4 py-2.5 text-right font-medium text-muted-foreground">Amount</th>
              </tr>
            </thead>
            <tbody>
              {bookings.map((b) => {
                const clientName = b.clients
                  ? `${b.clients.first_name} ${b.clients.last_name ?? ''}`.trim()
                  : 'Unknown'
                return (
                  <tr key={b.id} className="border-t border-border/20 hover:bg-muted/20">
                    <td className="px-4 py-2.5">{clientName}</td>
                    <td className="px-4 py-2.5 text-muted-foreground">
                      {b.services?.name ?? 'Appointment'}
                    </td>
                    <td className="px-4 py-2.5 text-muted-foreground tabular-nums text-xs">
                      {new Date(b.scheduled_at).toLocaleDateString('en-US', {
                        month: 'short',
                        day: 'numeric',
                        year: 'numeric',
                      })}
                    </td>
                    <td className="px-4 py-2.5 text-right tabular-nums">
                      ${(b.price_cents / 100).toLocaleString()}
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  )
}

// ── Main Tabs Component ───────────────────────────────────────────────────────

export function GuestEngagementTabs({ id, isOwner }: GuestEngagementTabsProps) {
  return (
    <Tabs defaultValue="overview">
