import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { rawQuery } from '@/lib/supabase/raw-query'

interface EngagementRow {
  artist_id: string
  start_date: string
  end_date: string
}

interface CommissionRow {
  booking_id: string
  total_cents: number
}

/**
 * GET /api/guest-artists/[id]/engagement-bookings
 * Returns bookings during the engagement period for a guest artist,
 * along with running revenue + commission tallies.
 *
 * [id] = engagement UUID (not artist UUID)
 */
export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { id } = await params

  try {
    const supabase = await createClient()

    // Fetch engagement details
    const { data: engagement, error: engError } = await rawQuery<EngagementRow>(
      supabase,
      'guest_artist_engagements',
    )
      .select('artist_id, start_date, end_date, studio_id')
      .eq('id', id)
      .single()

    if (engError || !engagement) {
      return NextResponse.json({ error: 'Engagement not found' }, { status: 404 })
    }

    const engRow = engagement as EngagementRow & { studio_id: string }

    // Verify studio ownership
    if (engRow.studio_id !== authUser.studioId) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
    }

    // Fetch bookings within engagement date range
    const { data: bookings, error: bError } = await supabase
      .from('bookings')
      .select(`
        id,
        scheduled_at,
        status,
        price_cents,
        clients(first_name, last_name),
        services(name)
      `)
      .eq('studio_id', authUser.studioId)
      .eq('artist_id', engRow.artist_id)
      .gte('scheduled_at', `${engRow.start_date}T00:00:00Z`)
      .lte('scheduled_at', `${engRow.end_date}T23:59:59Z`)
      .in('status', ['completed', 'confirmed', 'pending', 'in_progress'])
      .order('scheduled_at', { ascending: false })

    if (bError) {
      logger.error({ err: bError }, 'engagement-bookings: bookings fetch failed')
      return NextResponse.json({ error: 'Failed to fetch bookings' }, { status: 500 })
    }

    const bookingList = bookings ?? []
    const totalRevenueCents = bookingList
      .filter((b) => b.status === 'completed')
      .reduce((sum, b) => sum + b.price_cents, 0)

    // Sum commission records for this artist during the period
    const completedIds = bookingList
      .filter((b) => b.status === 'completed')
      .map((b) => b.id)

    let totalCommissionCents = 0
    if (completedIds.length > 0) {
      const { data: commissions } = await supabase
        .from('commission_records')
        .select('total_cents')
        .eq('artist_id', engRow.artist_id)
        .eq('studio_id', authUser.studioId)
        .in('booking_id', completedIds)

      totalCommissionCents = (commissions ?? []).reduce(
        (sum, c: CommissionRow) => sum + (c.total_cents ?? 0),
        0,
      )
    }

    return NextResponse.json({
      data: bookingList,
      total_revenue_cents: totalRevenueCents,
      total_commission_cents: totalCommissionCents,
    })
  } catch (err) {
    logger.error({ err }, 'engagement-bookings GET failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

